import csv
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

FACTORS = {
    "kg": Decimal(1),
    "g": Decimal("0.001"),
    "lb": Decimal("0.45359237"),
    "oz": Decimal("0.028349523125"),
}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

DELIMITED = {
    "east": {"delim": ",", "quote": True, "cols": {"id", "type", "shipped", "gross", "net", "status", "note"},
             "id": "id", "type": "type", "date": "shipped", "weight": "gross", "status": "status",
             "base_date": "YMD", "base_unit": "kg", "unit_dir": "unit", "date_dir": "dates"},
    "harbor": {"delim": "|", "quote": False, "cols": {"rec", "ref", "date", "weight", "state"},
               "id": "ref", "type": "rec", "date": "date", "weight": "weight", "status": "state",
               "base_date": "iso", "base_unit": "kg", "unit_dir": "unit", "date_dir": "dates"},
    "lakeside": {"delim": ",", "quote": True,
                 "cols": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
                 "id": "id", "type": "kind", "date": "shipped", "weight": "gross_kg", "status": "status",
                 "base_date": "iso", "base_unit": "kg", "unit_dir": "unit", "date_dir": "dates",
                 "field_unit": "kg"},
    "river": {"delim": "\t", "quote": False, "cols": {"t", "ref", "shipped", "weight", "status"},
              "id": "ref", "type": "t", "date": "shipped", "weight": "weight", "status": "status",
              "base_date": "MM/DD/YYYY", "base_unit": "kg", "unit_dir": "weight unit",
              "date_dir": "date format"},
    "west": {"delim": ";", "quote": False, "cols": {"id", "typ", "shipped", "weight", "status", "note"},
             "id": "id", "type": "typ", "date": "shipped", "weight": "weight", "status": "status",
             "base_date": "DD.MM.YYYY", "base_unit": "kg", "unit_dir": "weight unit",
             "date_dir": "date format", "decimal": ","},
}

HARBOR_STATUS = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                 "RET": "returned", "HLD": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}


def read_bytes(path):
    with open(path, "rb") as handle:
        data = handle.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be")
    match = re.search(rb"^#\s*charset:\s*([\w.:-]+)", data[:2000], re.M | re.I)
    encoding = match.group(1).decode("ascii") if match else "utf-8"
    return data.decode(encoding).lstrip("\ufeff")


def split_lines(text):
    lines = text.split("\n")
    return [line[:-1] if line.endswith("\r") else line for line in lines]


def id_number(text):
    match = re.search(r"(\d+)\s*$", text.strip())
    if not match:
        return None
    if not re.match(r"^\s*sh", text, re.I):
        return None
    return int(match.group(1))


def norm_status(text):
    return re.sub(r"[\s\-]+", "_", text.strip().lower())


def counted(status):
    return status in ("delivered", "delivered_late")


def parse_number(text, decimal="."):
    text = text.strip()
    if decimal == ",":
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Decimal(text)


def weight_kg(text, unit, decimal="."):
    text = text.strip()
    match = re.match(r"^([-+0-9.,]+)\s*([A-Za-z]+)$", text)
    if match:
        text, unit = match.group(1), match.group(2).lower()
    return parse_number(text, decimal) * FACTORS[unit]


def norm_unit(text):
    if not text:
        return None
    token = re.split(r"[\s(]", text.strip().lower())[0]
    return token if token in FACTORS else None


def to_utc_date(value):
    return value


def parse_date(text, form):
    text = text.strip()
    form = re.sub(r"\s+", "", (form or "")).upper()
    if re.match(r"^\d{4}-\d\d-\d\d[T ]", text):
        stamp = datetime.fromisoformat(text.replace(" ", "T", 1))
        if stamp.tzinfo is not None:
            stamp = stamp.astimezone(timezone.utc)
        return stamp.date()
    match = re.match(r"^(\d{4})-(\d\d)-(\d\d)$", text)
    if match:
        return date(*map(int, match.groups()))
    match = re.match(r"^(\d\d?)\.(\d\d?)\.(\d{4})$", text)
    if match:
        return date(int(match.group(3)), int(match.group(2)), int(match.group(1)))
    match = re.match(r"^(\d\d?)-(\d\d?)-(\d{4})$", text)
    if match:
        first, second, year = map(int, match.groups())
        if form.startswith("MM"):
            return date(year, first, second)
        return date(year, second, first)
    match = re.match(r"^(\d\d?)/(\d\d?)/(\d{4})$", text)
    if match:
        first, second, year = map(int, match.groups())
        if form.startswith("DD"):
            return date(year, second, first)
        return date(year, first, second)
    match = re.match(r"^(\d\d?)\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})$", text)
    if match:
        return date(int(match.group(3)), MONTHS[match.group(2).lower()], int(match.group(1)))
    if re.match(r"^\d{8}$", text):
        return date(int(text[:4]), int(text[4:6]), int(text[6:]))
    if re.match(r"^\d{7}$", text):
        return date(int(text[:4]), 1, 1) + timedelta(days=int(text[4:]) - 1)
    if re.match(r"^\d+(\.\d+)?$", text):
        return date(1899, 12, 30) + timedelta(days=int(float(text)))
    raise ValueError("bad date %r" % text)


def kind_of(text):
    text = (text or "").strip().lower()
    if text.startswith("c") or text.startswith("a"):
        return "correction"
    if text.startswith("v"):
        return "void"
    return "new"


def logical_records(lines, quote):
    pending = None
    for line in lines:
        if pending is not None:
            pending += "\n" + line
            if pending.count('"') % 2 == 0:
                yield pending
                pending = None
            continue
        if quote and line.count('"') % 2 == 1 and not line.startswith("#"):
            pending = line
            continue
        yield line
    if pending is not None:
        yield pending


def read_delimited(depot, text):
    spec = DELIMITED[depot]
    seq = None
    directives = {}
    header = None
    records = []
    for raw in logical_records(split_lines(text), spec["quote"]):
        if raw.startswith("#"):
            match = re.match(r"^#\s*([A-Za-z][\w ]*?)\s*[:=]\s*(.*)$", raw)
            if depot == "harbor":
                seq_match = re.match(r"^#harbor export seq=(\d+)", raw)
                if seq_match:
                    seq = int(seq_match.group(1))
            if match:
                name = match.group(1).lower()
                directives[name] = match.group(2).strip()
                if name == "seq":
                    seq = int(match.group(2))
            continue
        if not raw.strip():
            continue
        if spec["quote"]:
            fields = next(csv.reader([raw], delimiter=spec["delim"]))
        else:
            fields = raw.split(spec["delim"])
        stripped = [field.strip() for field in fields]
        if stripped and all(field in spec["cols"] for field in stripped):
            header = stripped
            continue
        if header is None:
            continue
        row_unit = None
        if len(fields) == len(header) + 1:
            for index, field in enumerate(stripped):
                if field.lower() in FACTORS:
                    row_unit = field.lower()
                    del fields[index]
                    break
        row = dict(zip(header, fields))
        number = id_number(row.get(spec["id"], ""))
        if number is None:
            continue
        kind = kind_of(row.get(spec["type"], ""))
        entry = {"number": number, "kind": kind}
        if kind != "void":
            unit = None
            raw_weight = row[spec["weight"]]
            if spec.get("field_unit"):
                unit = spec["field_unit"]
            elif row_unit:
                unit = row_unit
            else:
                unit = norm_unit(directives.get(spec["unit_dir"])) or spec["base_unit"]
            form = directives.get(spec["date_dir"], spec["base_date"])
            status = row[spec["status"]]
            if depot == "harbor":
                status = HARBOR_STATUS.get(status.strip().upper(), status)
            entry["status"] = norm_status(status)
            entry["kg"] = weight_kg(raw_weight, unit, spec.get("decimal", "."))
            entry["date"] = parse_date(row[spec["date"]], form)
        records.append(entry)
    return seq, records


def read_fixed(text):
    layouts = {
        "FW1": (42, ["id", 0, 9, "type", 9, 10, "date", 10, 17, "weight", 17, 25, "status", 25, 26]),
        "FW2": (43, ["type", 0, 1, "id", 1, 10, "date", 10, 18, "weight", 18, 26, "status", 26, 27]),
        "FW3": (41, ["id", 0, 9, "date", 9, 16, "type", 16, 17, "weight", 17, 24, "status", 24, 25]),
    }
    by_length = {length: name for name, (length, _) in layouts.items()}
    seq = None
    current = None
    records = []
    for line in split_lines(text):
        if line.startswith("#LAYOUT"):
            current = line.split()[1]
            continue
        if line.startswith("#SEQ"):
            seq = int(line.split()[1])
            continue
        if line.startswith("#") or line.startswith("\x0c") or not line.strip():
            continue
        if "SHIPMENT LISTING" in line:
            continue
        name = by_length.get(len(line), current)
        if name is None:
            continue
        length, parts = layouts[name]
        line = line.ljust(length)
        fields = {}
        for index in range(0, len(parts), 3):
            fields[parts[index]] = line[parts[index + 1]:parts[index + 2]]
        number = id_number(fields["id"])
        if number is None:
            continue
        kind = kind_of(fields["type"])
        entry = {"number": number, "kind": kind}
        if kind != "void":
            amount = Decimal(int(fields["weight"]))
            if name == "FW1":
                kg = amount * FACTORS["g"]
            elif name == "FW2":
                kg = amount / 100
            else:
                kg = amount / 10 * FACTORS["lb"]
            entry["kg"] = kg
            entry["date"] = parse_date(fields["date"], "")
            entry["status"] = FW_STATUS.get(fields["status"].strip().upper(), "")
        records.append(entry)
    return seq, records


def read_jsonl(text):
    seq = None
    records = []
    for line in split_lines(text):
        if not line.strip():
            continue
        value = json.loads(line)
        items = value if isinstance(value, list) else [value]
        for item in items:
            if not isinstance(item, dict):
                continue
            if "meta" in item and "id" not in item:
                meta = item["meta"]
                if isinstance(meta, dict) and "seq" in meta:
                    seq = int(meta["seq"])
                continue
            number = id_number(str(item.get("id", "")))
            if number is None:
                continue
            kind = kind_of(item.get("kind", "new"))
            entry = {"number": number, "kind": kind}
            if kind != "void":
                kg = None
                for key, val in item.items():
                    match = re.match(r"^weight_(kg|g|lb|oz)$", key.lower())
                    if match:
                        text = str(val)
                        kg = parse_number(text) * FACTORS[match.group(1)]
                if kg is None:
                    kg = weight_kg(str(item.get("weight", "0")), "kg")
                entry["kg"] = kg
                entry["date"] = parse_date(item["shipped_at"], "")
                entry["status"] = norm_status(item["status"])
            records.append(entry)
    return seq, records


def read_xml(data):
    root = ET.fromstring(data)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = norm_unit(root.get("weight-unit")) or "kg"
    records = []
    for element in root.iter("shipment"):
        number = id_number(element.get("id", ""))
        if number is None:
            continue
        kind = kind_of(element.get("type", "new"))
        entry = {"number": number, "kind": kind}
        if kind != "void":
            weight = element.find("weight")
            if weight is not None:
                text, unit = weight.text, norm_unit(weight.get("unit"))
            else:
                text, unit = element.get("weight"), norm_unit(element.get("weight-unit"))
            entry["kg"] = weight_kg(text, unit or root_unit)
            shipped = element.find("shipped")
            shipped_text = shipped.text if shipped is not None else element.get("shipped")
            entry["date"] = parse_date(shipped_text, "")
            status = element.find("status")
            entry["status"] = norm_status(status.text if status is not None else element.get("status", ""))
        records.append(entry)
    return seq, records


def read_export(depot, path):
    data = read_bytes(path)
    if depot == "central" or data.lstrip(b"\xef\xbb\xbf \r\n")[:5] == b"<?xml":
        return read_xml(data)
    text = decode(data)
    if depot in DELIMITED:
        return read_delimited(depot, text)
    if depot == "south":
        return read_fixed(text)
    if depot == "north":
        return read_jsonl(text)
    raise ValueError("unknown depot " + depot)


def money(value):
    return float(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        seq, records = read_export(depot, path)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))

    corrections = 0
    resends = 0
    current = {}
    for depot, items in exports.items():
        shipments = {}
        for _, _, records in sorted(items, key=lambda item: (item[0], item[1])):
            for record in records:
                number = record["number"]
                if record["kind"] == "new":
                    if number in shipments:
                        resends += 1
                    else:
                        shipments[number] = record
                elif record["kind"] == "correction":
                    shipments[number] = record
                    corrections += 1
                else:
                    shipments.pop(number, None)
                    corrections += 1
        current[depot] = shipments

    order = {depot: index for index, depot in enumerate(PRIORITY)}
    owners = {}
    for depot in current:
        for number in current[depot]:
            owners.setdefault(number, []).append(depot)
    handovers = sum(1 for depots in owners.values() if len(depots) > 1)

    depots_out = {depot: [0, Decimal(0)] for depot in exports}
    months = {}
    for number, depots in owners.items():
        winner = min(depots, key=lambda depot: order.get(depot, len(order)))
        record = current[winner][number]
        if not counted(record["status"]):
            continue
        depots_out[winner][0] += 1
        depots_out[winner][1] += record["kg"]
        key = "%04d-%02d" % (record["date"].year, record["date"].month)
        bucket = months.setdefault(key, [0, Decimal(0)])
        bucket[0] += 1
        bucket[1] += record["kg"]

    result = {
        "depots": {d: {"shipments": v[0], "total_kg": money(v[1])} for d, v in sorted(depots_out.items())},
        "months": {m: {"shipments": v[0], "total_kg": money(v[1])} for m, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(result, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
